import json,html,pathlib
B=json.load(open('dev/transition-baseline.json')); C=json.load(open('dev/transition-controls.json')); P=json.load(open('dev/transition-probability-controls.json'))
parts=[]
def p(s):parts.append('<p>'+s+'</p>')
def h(s):parts.append('<h2>'+html.escape(s)+'</h2>')
def table(cols,rows):parts.append('<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(str(c))+'</th>' for c in cols)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(c))+'</td>' for c in row)+'</tr>'for row in rows)+'</tbody></table></div>')
def pct(x):return '—'if x is None else f'{100*x:.2f}%'
def pp(x):return f'{100*x:+.3f} pp'
def num(x):return '—'if x is None else f'{x:.2f}'
p('<strong>Diagnostic only. No production code, balance, block multipliers, tempo defaults, or deployed game was changed.</strong> The putback-block experiment was not implemented.')
h('Result and scope')
p('<strong>Classification D: overloaded transition state plus repeated upstream rewards.</strong> Coach tempo can label a completed half-court action as transition. Every Running + PNR evaluation in this fixture came from that late tempo roll. Screen advantage also feeds multiple accuracy/open-look calculations; this establishes overlapping inputs, not that every PNR modifier should be removed.')
p('Exact reference fixture: creation seed 61005, 30 teams, 15-player preseason rosters, 82-game default league settings, first ten circle rounds with alternating venues, 150 games, ten appearances/team, game seeds 100000–100149. Preseason state resets for each game. Production normal-mode engine, current no-sag implementation. All 150 instrumented games and complete post-game league states matched uninstrumented execution exactly; FGA accounting reconciled. The rerun reproduced PPG 123.84, pace 102.38, ORtg 120.9611, 2P 56.3908%, 3P 38.0049%.')
p('Terminology: an <em>evaluation</em> includes a shooting-foul miss that is not recorded as an FGA. Observed FG%, contest, player ratings and block rates below use recorded attempts unless stated otherwise. Base/context/final probability averages use evaluations; final probability includes the actual foul-specific adjustment and clamps, but is conditional on not being blocked. “Event-driven” means the code received a rebound/steal trigger; it does not prove the defense was actually unset.')
h('1. Actual transition flag sources')
table(['Source / location','Condition and probability','Meaning'],[
['attributes.js: recordTurnover','defender is non-null; certain after credited steal','A steal sets transitionTeam=1-side. A non-steal turnover does not.'],
['attributes.js: primary miss rebound','board.offensive is false; certain after that rebound','Any primary-shot DREB, including recovery of a blocked shot; no speed, long-rebound or defender-position gate.'],
['attributes.js: finishRebound','board.offensive is false; certain after that rebound','DREB after putback/kick-out misses or final missed, non-retained/nontechnical FT.'],
['attributes.js: possessionCore entry','transitionAdvantage = transitionTeam === side; token cleared immediately','Event-derived flag passed into tendencyPossession. Reset again at period boundary.'],
['attributes.js: possessionCore, after decisions/turnover gates','transition = transitionAdvantage || random() < coach.tempo/250','New late boolean merges event opportunity and tempo. Tempo roll is skipped when event flag is true; can occur in half-court, PNR, ISO or recursive possession.'],
['tendencies.js: early-three wrapper','event flag × random threshold: clamp(tempo/140,0,.65) × three tendency × speed/100','Selects earlyThree; tempo here includes user Fast +20 / Slow −20. Does not create a new event flag.'],
['pick-and-roll.js: tendencyPossession','if context.transition: bypass PNR wrapper','PNR is half-court at initiation; it does not set transition itself.']])
p('No separate long-rebound, fast-inbound, opponent-made-basket, or generic “possession changed” transition trigger exists. Offensive rebounds do not set an event token. A later coach-tempo roll can still generate Running Layup after all of these situations. The possession machine’s transition(...) method changes action phases; it is not the basketball fast-break flag.')
h('2. Running layup origins and prevalence')
r=B['running']; n=r['evaluations']; event=n-B['origins']['coach tempo']['evaluations']
p(f'Primary rim: {B["primaryRim"]["evaluations"]:,} evaluations. Running Layup: {n:,} ({pct(r["shareOfRim"])}), {r["attempts"]:,} FGA, {num(r["perTeamGame"])} evaluations/team/game and {num(r["attemptsPerTeamGame"])} FGA/team/game. Both teams combined: {num(n/150)} evaluations/game. Event-driven share {pct(event/n)}; tempo-only share {pct(1-event/n)}; other independent sources 0%.')
table(['Mutually exclusive primary origin','Evaluations','Share','FGA'],[[k,v['evaluations'],pct(v['evaluations']/n),v['attempts']]for k,v in B['origins'].items()])
if 'recursiveRunningOrigins'in B:
 p(f'Additionally, {B["recursiveRunning"]} Running Layup evaluations occurred in the recursive offensive-rebound path. They are outside the reference primary-rim denominator. Complete origins including them:')
 table(['Origin, all paths','Evaluations','FGA'],[[k,v['evaluations'],v['attempts']]for k,v in B['allRunningOrigins'].items()])
p('Event-driven share is an upper bound on genuine fast-break quality: every DREB is treated as an opportunity, and the flag has no time-since-event expiry or requirement that the defense is unsettled.')
h('3. Basketball history before Running Layup')
p('Instrumented event branches, not PBP string parsing. Table records the last basketball event at possessionCore entry, before pass/drive/PNR action selection. Origins and entry history can differ if a technical free throw intervenes. It does not claim the last event immediately before release was a rebound: passes/screens normally follow.')
table(['Preceding entry event','Count','Share'],[[k,v['count'],pct(v['share'])]for k,v in B['history'].items()])
p('Made-basket entries: 449; made-final-FT entries: 99. These demonstrate Running Layup after dead-ball scoring events without an explicit fast-inbound model. A residual missed-shot entry is reported as observed rather than inventing a rebound or inbound. Start-of-period entries are also possible from the tempo roll. Offensive-rebound recursive evaluations are reported separately above.')
if 'runningAfterFoulTrace'in B:table(['Running with foul phase in machine trace','Evaluations'],[[k,v['evaluations']]for k,v in B['runningAfterFoulTrace'].items()])
h('4. Time and clock semantics')
p(f'Mean assigned root offensive window: {num(r["window"])} seconds. Mean remaining machine shot clock at Running Layup evaluation: {num(r["shotClock"])} seconds (about {num(24-r["shotClock"])} nominal action seconds consumed).')
table(['Shot clock remaining','Evaluations','Share'],[[k,v['count'],pct(v['share'])]for k,v in B['clockBuckets'].items()])
table(['Origin','Mean clock remaining','Minimum','Maximum'],[[k,num(v['mean']),v['min'],v['max']]for k,v in B['clockByOrigin'].items()])
p('46/1,397 evaluations occur with nine seconds or less remaining; six occur with four or less. An event-generated Running Layup survives down to one second; a tempo-generated one occurs at four seconds. Neither selection requires early clock. Thus even an authentic initiating rebound/steal can retain Running treatment deep into an action sequence.')
p('The game assigns each root possession a fixed window of 60/(2 × possessions-in-this-minute) seconds. Action-machine costs independently subtract seconds from 24 (14 on a rebound reset). PBP clock updates depend on logging, clamp to that window and stop after the log cap. These are not a continuously integrated physical possession clock; assigned window and nominal action seconds can diverge. No measured real elapsed fast-break duration can be claimed.')
h('5. Matched coach-tempo controls')
p('100 games/group, same first 100 matchups and seeds 100000–100099, identical copied preseason rosters/ratings/tendencies, settings, coaching systems, staff and skill ratings. Only every coach’s preferred tempo was set to 20, 50 or 80 in disposable fixtures. No saved career or production defaults changed. First three games/group also passed full game/state instrumentation parity; all FGA totals reconciled. Transition rates use evaluations reaching primary/recursive shot selection, not all root possessions.')
table(['Tempo','Transition flag','Event flag','Tempo-only flag','Pace','Running eval/team/G','Running FGA/team/G','Share of rim','Rim FG','2P','PPG','ORtg'],[[r['tempo'],pct(r['transition']['rate']),pct(r['transition']['eventRate']),pct(r['transition']['tempoRate']),num(r['league']['pace']),num(r['running']['perTeamGame']),num(r['running']['attemptsPerTeamGame']),pct(r['running']['shareOfRim']),pct(r['primaryRim']['FG']),pct(r['league']['twoP']),num(r['league']['PPG']),num(r['league']['ORtg'])]for r in C])
p('Coach tempo affects both quantity and finishing treatment. With both coaches at 20/50/80, the core pre-rounding possession target is 94/100/106 before existing settings, fatigue, random variation and overtime. Conditional late tempo-roll probability is 8%/20%/32%; the observed tempo-only rate is lower because event-triggered evaluations bypass the roll. Low→high measured pace rises 11.70, Running evaluations/team/game rise 1.68, and transition rate rises 15.58 pp.')
p('Overall ORtg is not monotonic (121.57 → 119.57 → 121.18); rim FG is also not monotonic. This sample proves higher tempo grants Running treatment more often, not a reliable aggregate efficiency gain. Tempo also affects early-three selection and the existing above-50 handling-turnover term: max(0,tempo−50)/50 × (1−tempoControl/120) × .04. Shot mix, RNG divergence, fatigue and other consequences remain live in these full-game controls.')
h('6. Exact Running versus Driving effects')
table(['Property','Driving','Running'],[['Effective finishing mix','75% layup + 25% speed','80% layup + 20% speed'],['Variant accuracy adjustment','0','+.055'],['Variant block multiplier','1','.5'],['Additional running-specific contest/foul/physical modifier','None','None'],['Selection','40 weight among eligible non-transition variants','Sole non-floater layup option when merged transition is true']])
p('Mixed-skill difference is .05 × (effective layup − effective speed), zero under equal 75 ratings. Base shot-key adjustment is separate: the runningLayup key carries −.01, whereas drivingLayup and PNR layup overrides carry zero. In this fixture 454/1,397 Running variants use the −.01 key; 943 use zero. Thus mean shotVariant = .055 − .01×454/1397 = .05175018, or +5.175 pp. Across all primary rim evaluations that contributes +2.592 pp. The direct variant reward alone contributes +2.755 pp before the key offset.')
table(['Contest','Variant','Make probability','Block probability','Expected non-foul FG'],[[('Contested'if r['contest']else'Uncontested'),r['variant'],pct(r['probability']),pct(r['blockRisk']),pct(r['expectedNonFoulFG'])]for r in P['results']])
p('Controls use actual engine probability code, identical 75-rated clones with the same build, same drive action, 50% block tendency, neutral home court and modifiers, default sliders. Uncontested: accuracy alone at Driving block risk contributes +5.23875 pp; halving block risk at the new Running make chance adds +1.650625 pp; total +6.889375 pp. Contested: total +6.818125 pp. Block probability falls 4.75%→2.375% (−2.375 pp). These expected values exclude shooting-foul branches, not observed simulation percentages.')
h('7. Observed Running versus Driving')
cols=['Variant','Evaluations','FGA','Finishing','Mixed skill','Defender rim','Contest','PNR','Uncontested','Final P / FGA','Block rate','Foul/eval','Observed FG']
table(cols,[[label,v['evaluations'],v['attempts'],num(v['finishing']),num(v['effectiveSkill']),num(v['rimDefense']),pct(v['contest']),pct(v['PNR']),pct(v['uncontested']),pct(v['recordedFinal']),pct(v['blockRate']),pct(v['foulRate']),pct(v['FG'])]for label,v in [('Running',B['running']),('Driving',B['driving'])]])
p('Running shooters have only a modest mixed-skill advantage and face higher average rim defense, but Running attempts have fewer contests and much lower observed block rates. This is observational selection, not a matched causal effect.')
rows=[]
for k,v in B['strata'].items():
 if all(x in v and v[x]['attempts']>=30 for x in ['Running Layup','Driving Layup']):
  for label,r in v.items():rows.append([k,label,r['attempts'],num(r['effectiveSkill']),num(r['rimDefense']),pct(r['recordedFinal']),pct(r['FG'])])
table(['Mixed-skill band / contest / action','Variant','FGA','Skill','Defender rim','Final P / FGA','FG'],rows)
p('Strata retain meaningful defender/context differences; small cell samples are noisy. Equal-rating deterministic controls above isolate the actual variant effects more cleanly.')
h('8. PNR overlap and repeated rewards')
table(['Combination','Evaluations','Share of Running','FGA','Base + physical','Context','Net context','Observed FG'],[[k,v['evaluations'],pct(v['share']),v['attempts'],pct(v['base']),pct(v['context']),pp(v['contextDelta']),pct(v['FG'])]for k,v in B['stacks'].items()])
p('All 405 Running+PNR evaluations are tempo-generated. Actual event-transition bypasses the half-court PNR wrapper. After the PNR decision has returned, the late tempo roll overrides the layup variant to Running. PNR itself is not a separate transition source.')
p('Distinct inputs include the ball handler’s drive/finishing matchup, roll skill versus rim defense, coverage and help arrival. However screen.boost (14 for excellent, 4 for soft) is reused in (1) defender recovery/openLook probability, (2) PNR-drive shotAdjustment at .0006×boost before clamping, and (3) the primary direct .001×boost. OpenLook then makes PNR contest false, changing −.015 to +.015. The same screen therefore has multiple scoring channels, in addition to a tempo-driven +.055 Running reward and reduced block multiplier. This is code-level overlapping reward, not a conclusion based on labels. The Running bonus and PNR boost are generated from different upstream states; the incoherence is treating a tempo roll as fast-break finishing quality after an explicitly half-court PNR.')
p('Positive screen boost means >0, not only an excellent screen; the 300-case group includes soft and excellent handler-drive screens. Roll finishes have zero direct handler boost. Open/uncontested and help-arrival states are related but not equivalent: an open PNR roll requires no help arrival plus hedge/blitz coverage.')
h('9. Running modifier decomposition')
table(['Modifier','Nonzero evaluations','Mean when applied','Contribution per Running eval'],[[k,v['count'],pp(v['meanApplied']),pp(v['contribution'])]for k,v in B['modifiers'].items()])
p('The sum is +6.0703 pp across Running evaluations; every existing positive and negative term is included. No modifier was removed or capped.')
h('10. Transition threes and defensive consequences')
t=B['transitionThrees'];p(f'The same late merged flag enables the runningThree shot key and Running 3PT label. The earlier earlyThree branch uses the narrower event flag. This fixture contains {t["attempts"]:,}/{t["total3PA"]:,} recorded transition-labelled threes ({pct(t["share"])}): {t["early"]:,} earlyThree attempts and {t["attempts"]-t["early"]:,} other runningThree attempts. Of all transition-labelled threes, 101 are tempo-only and 2,224 event-origin. The earlier approximate 17% figure is not reproduced by this exact fixture/definition; it must not be silently reused.')
p('The early branch marks openLook true and can use a pass or pull-up. Its gate includes coach tempo, three tendency and speed. The late tempo flag does not retroactively set earlyThree. Running three treatment does not include the +.055 layup reward. A future layup-specific semantic change should preserve these two existing three-point pathways deliberately.')
table(['Defensive component','Actual consequence'],[['Defender selection','Late flag sampled after defender selection. No generic transition defender replacement; event flag indirectly changes available actions by bypassing PNR. Existing ISO help and archetype matching still apply.'],['Contest','Computed before late transition roll. No transition-specific contest bonus; selected early-three openLook affects shot modifiers, while PNR contest uses !openLook.'],['Help','No generic transition help-arrival test. Existing PNR/ISO help behavior remains; event transition bypasses PNR.'],['Blocks','Running layup variant multiplies block risk by .5. Early/open three has its own existing block and contest multipliers.'],['Fouls','No direct transition/running term in shooting-foul probability. Shot/player/action selection may affect risk; foul makes still use .7×chance before clamps.'],['Ratings / physical matchup','No direct transition buff to defender ratings or physical matchup. Running changes shooter skill weights; physical matchup uses action, kind, contest and builds.'],['Timing','No expiry of event transition based on shot-clock consumption; tempo roll itself has no clock gate.']])
h('11. Frozen arithmetic counterfactual — not simulation')
table(['Recorded evaluations','N','Original final make P','Without only direct +.055','Difference'],[[k,v['evaluations'],pct(v['final']),pct(v['counterfactual']),pp(v['counterfactual']-v['final'])]for k,v in B['frozen'].items()])
p('Subtraction occurs before existing shooting-rate multiplication, branch-specific .7 foul adjustment, probability clamps, shot sliders and home court. The −.01 base-key adjustment, shooter weighting, actual branch, defender, block state, all other modifiers and RNG outcomes are frozen. All-evaluation mean is 67.6303%→62.3280% (−5.3023 pp). No attempt outcomes are rerolled and no league PPG is inferred. Recorded-FGA subset is selected using original outcomes; it is not an unbiased estimate of a resimulated FG%.')
h('12. Recommended next experiment — not implemented')
p('<strong>One change: gate the Running Layup variant on event-derived transitionAdvantage rather than the late merged tempo flag.</strong> Preserve the current tempo/possession logic, three-point pathways, shot-selection tendencies, +.055 coefficient and .5 block coefficient. Apply the existing Running variant treatment only when the event gate qualifies; do not separately retune those coefficients. Then rerun this identical fixture and controls. Event-only gating would still not prove a true fast break, since all DREBs and late-clock continuations currently qualify; investigate that separately after the single-variable result.')
h('Reproduction and safeguards')
p('Production reference: commit 2748e11d3205246762bdd68e001a9f0495551ae9. Source inspected: dist/attributes.js (simulateAttributeGame, recordTurnover, possessionCore, finishRebound, runMinute), dist/tendencies.js (layupOptions, contextualLayup, tendencyShotWeights, threePointFinish and early-three wrapper), dist/pick-and-roll.js (pnrScreen, playPickAndRoll and wrapper), dist/coaching.js (coachFor/coachingSkill/coachFit), dist/possession-engine.js (createPossessionMachine). No production diff or deployment.')
p('Run from the repository: node dev/audit-transition.cjs baseline 150; node dev/audit-transition.cjs controls 100; node dev/transition-probability-controls.cjs; python3 dev/report-transition.py. Observer code is injected into the development VM only, never shipped. Controls modify disposable in-memory fixture copies only. JSON result files are beside the diagnostic scripts.')
body=''.join(parts)
output=pathlib.Path('/workspace/scratch/cbd19dbea1f8/Hoops-Dynasty-Transition-Running-Layup-Audit.html')
output.write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hoops Dynasty — Transition & Running Layup Audit</title><style>body{font:16px/1.55 system-ui,sans-serif;color:#172535;background:#f5f7fa;max-width:1160px;margin:auto;padding:32px}h1{line-height:1.2}h2{margin-top:2em;color:#163e68}table{border-collapse:collapse;width:100%;font-size:14px;background:white}td,th{border:1px solid #d5dfe9;padding:9px;text-align:left;vertical-align:top}th{background:#e4ecf5}.scroll{overflow-x:auto;margin:20px 0}p{max-width:1050px}strong{color:#153556}@media print{body{padding:0;background:white;font-size:11px}table{font-size:9px}.scroll{overflow:visible}h2{break-after:avoid}}</style><h1>Hoops Dynasty<br>Transition & Running Layup Semantics Audit</h1><p>7 October 2026 · Diagnostic-only · Current no-sag baseline</p>'+body+'</html>')
